#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;
const int MOD_CONST=1e9+7;
typedef long long LL;
LL number;
int length, base, totalSum, position, digitsArr[110];
void addModulo(int &x, int y, int m) {
    x += y; if (x >= m) x -= m;
}
struct Mat {
    int mat[35][35];
    Mat() { memset(mat, 0, sizeof(mat)); }
    Mat operator*(const Mat &other) const {
        Mat result;
        for (int k=0; k<=base; k++)
            for (int i=0; i<=base; i++)
                if (mat[i][k])
                    for (int j=0; j<=base; j++)
                        if (other.mat[k][j])
                            result.mat[i][j] = (1LL * mat[i][k] * other.mat[k][j] + result.mat[i][j]) % MOD_CONST;
        return result;
    }
} answerMat, sMat[75][35], prefixMat[75][35], suffixMat[75][35];

void parseNumber(LL num) {
    LL temp = num;
    length=0;
    while (temp) {
        digitsArr[++length] = temp % base;
        temp /= base;
    }
    reverse(digitsArr+1, digitsArr+length+1);
}

int main() {
    scanf("%lld%d", &number, &base);
    parseNumber(number);
    for (int i=0; i<base; i++) {
        for (int j=0; j<=base; j++) sMat[0][i].mat[j][j]=1;
        for (int j=0; j<=base; j++) sMat[0][i].mat[i][j]=1;
    }
    for (int i=1; i<=length; i++) {
        prefixMat[i-1][0]=sMat[i-1][0];
        suffixMat[i-1][base-1]=sMat[i-1][base-1];
        for (int j=1; j<base; j++) prefixMat[i-1][j]=prefixMat[i-1][j-1]*sMat[i-1][j];
        for (int j=base-2; j>=0; j--) suffixMat[i-1][j]=sMat[i-1][j]*suffixMat[i-1][j+1];
        for (int j=0; j<base; j++)
            if (j) sMat[i][j]=suffixMat[i-1][j]*prefixMat[i-1][j-1];
            else sMat[i][j]=suffixMat[i-1][j];
    }
    for (int i=0; i<=base; i++)
        for (int j=0; j<=base; j++)
            answerMat.mat[i][j]=(i==j);
    position=0;
    for (int i=1; i<=length; i++) {
        if (digitsArr[i]) {
            if (position+digitsArr[i]-1>=base) {
                for (int j=position; j<base; j++) answerMat=answerMat*sMat[length - i][j];
                for (int j=0; j<=(position+digitsArr[i]-1)-base; j++) answerMat=answerMat*sMat[length - i][j];
            } else {
                for (int j=position; j<=position+digitsArr[i]-1; j++) answerMat=answerMat*sMat[length - i][j];
            }
            addModulo(position, digitsArr[i], base);
        }
    }
    for (int i=0; i<=base; i++) addModulo(totalSum, answerMat.mat[i][base], MOD_CONST);
    printf("%d\n", totalSum);
    return 0;
}
